import xml.etree.ElementTree as ET

# Parse h1.xml directly
tree = ET.parse("/Users/wangyifan/Projects/auto_adapter2.0/AA1/assets/mjcf/h1/h1.xml")
root = tree.getroot()

# --- Joints ---
joints = {}
for jnt in root.iter("joint"):
    name = jnt.get("name")
    axis = jnt.get("axis", "0 0 1")
    rng  = jnt.get("range", "0 0").split()
    lo, hi = float(rng[0]), float(rng[1])
    # find parent body
    parent_body = None
    for body in root.iter("body"):
        for child in body:
            if child.tag == "joint" and child.get("name") == name:
                parent_body = body.get("name")
    joints[name] = {"axis": axis, "range": [lo, hi], "parent_body": parent_body}

print("=== JOINTS ===")
for n, v in joints.items():
    print(f"  {n}: axis={v['axis']}, range={v['range']}, body={v['parent_body']}")

# --- Actuators ---
print("\n=== ACTUATORS ===")
actuators = {}
for act in root.iter("motor"):
    name = act.get("name")
    joint = act.get("joint")
    ctrl = act.get("ctrlrange", "0 0").split()
    lo, hi = float(ctrl[0]), float(ctrl[1])
    actuators[name] = {"joint": joint, "ctrlrange": [lo, hi]}
    print(f"  {name}: joint={joint}, ctrlrange=[{lo},{hi}]")

# --- Sites ---
print("\n=== SITES ===")
for site in root.iter("site"):
    print(f"  {site.get('name')} in body context")

# --- Equality / Weld ---
print("\n=== EQUALITY ===")
eq = root.find("equality")
if eq is not None:
    for child in eq:
        print(f"  {child.tag}: {child.attrib}")
else:
    print("  None")
